 function loadScannerCharts(){const frame=['1','5','d'].includes(chartFrame)?chartFrame:'1';slots=Array.from({length:4},(_,i)=>({inst:rows[i]?{...rows[i],secType:'STK',exch:'SMART',mult:1,brokerId:true}:null,frame}));activeSlot=0;selected=slots[0].inst;chartFrame=frame;grid=true;layout=frame==='5'?'m5':frame==='d'?'daily':'m1';hover=null;stage='trade';saveDesk();a.sync();a.render();slots.filter(s=>s.inst).forEach(s=>bars(s.inst.symbol));live();}
