 async function saveSource(form){if(jobs.has('source-save'))return;const field=form.querySelector('#guns-fmp-key');let key=field.value.trim();field.value='';jobs.add('source-save');const button=form.querySelector('button');button.disabled=true;sourceNotice='Saving on this server…';put('guns-source-notice',esc(sourceNotice));const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);try{const response=await fetch('/data/guns_credentials',{method:'POST',headers:{'Content-Type':'application/json','X-Paper-Desk-Settings':'1'},body:JSON.stringify({key}),signal:ctl.signal});key='';if(!response.ok)throw Error(response.status===403?'Open localhost on the computer running Paper Desk to save credentials.':response.status===400?'Invalid key format. Check your FMP key.':'Could not save settings; check the local server and folder permissions.');sourceNotice='Saved on this Paper Desk server; active now. Coverage still depends on your FMP subscription. Use Scan now or reselect the company to retry.';for(const k of Object.keys(errors))if(k.startsWith('float:'))delete errors[k];for(const k of Object.keys(times))if(k.startsWith('float:'))delete times[k];}catch(e){sourceNotice=e.name==='AbortError'?'Save timed out; check the local server and retry.':e instanceof TypeError?'Cannot reach the local Paper Desk server.':e.message;}finally{key='';clearTimeout(timer);jobs.delete('source-save');button.disabled=false;put('guns-source-notice',esc(sourceNotice));live();}}
